  var VOL_SR_STRONG_MULT = 1.5;  // S/R break >= 1.5x = very-high conviction
  var VOL_SR_WEAK_MULT = 0.8;    // 0.8-1.5x = medium, < 0.8x = likely fakeout
  var VOL_EOD_FLAG_MULT = 1.3;   // full-day vol >= 1.3x avg flags the session
