        var amt = (e.headlineAmount != null) ? cxDollars(e.headlineAmount) : '';
        var filed = e.filed ? ('Latest filed: ' + cxDollars(e.filed.val) + (e.filed.asOf ? ' (period to ' + String(e.filed.asOf).slice(0,10) + ')' : '')) : '';
