    if (retPct != null) bits.push('<b class="' + (retPct >= 0 ? 'rot-up' : 'rot-down') + '">' + (retPct >= 0 ? '+' : '') + fmt(retPct, 2) + '%</b>');
    if (rMultiple != null) bits.push('<b class="' + (rMultiple >= 0 ? 'rot-up' : 'rot-down') + '">' + (rMultiple >= 0 ? '+' : '') + fmt(rMultiple, 2) + 'R</b>');
